<?php $fav= $user ? (bool)\Aurelle\Database::one('SELECT user_id FROM favorites WHERE user_id=? AND listing_id=?',[$user['id'],$p['id']]) : false; ?>
<article class="property-card" data-property="<?= e($p['id']) ?>"><a href="/property?id=<?= e($p['id']) ?>" class="property-image"><?php if ($p['cover_url']): ?><img src="<?= e($p['cover_url']) ?>" alt="Illustrative interior of <?= e($p['title']) ?>" loading="lazy"><?php else: ?><div class="image-placeholder">Veyra Estates</div><?php endif ?><span class="property-tag"><?= $p['purpose']==='rent'?'FOR RENT':'FOR SALE' ?></span></a><form class="favorite-form" action="/favorite" method="post"><?= csrf() ?><input type="hidden" name="id" value="<?= e($p['id']) ?>"><button class="favorite <?= $fav?'selected':'' ?>" aria-label="<?= $fav?'Remove from':'Add to' ?> saved homes"><?= icon('heart') ?></button></form><div class="property-info"><div class="price-line"><strong><?= money($p['price_minor']) ?><?= $p['purpose']==='rent'?'<small> / month</small>':'' ?></strong><span class="demo-label">DEMO HOME</span></div><h3><a href="/property?id=<?= e($p['id']) ?>"><?= e($p['title']) ?></a></h3><p class="location"><?= icon('pin') ?><?= e($p['neighborhood'] ?? $p['city']) ?>, <?= e($p['city']) ?></p><div class="property-specs"><span><?= icon('bed') ?><?= e($p['bedrooms']) ?> beds</span><span><?= icon('bath') ?><?= (float)$p['bathrooms'] ?> baths</span><span><?= icon('area') ?><?= number_format((float)$p['floor_area']) ?> <?= e($p['area_unit']) ?></span></div><div class="card-bottom"><span><?= e($p['property_type']) ?></span><label><input type="checkbox" data-compare="<?= e($p['id']) ?>"> Compare</label></div></div></article>
